import yesman.epicfight.world.capabilities.EpicFightCapabilities;
import yesman.epicfight.world.capabilities.entitypatch.LivingEntityPatch;
import yesman.epicfight.world.capabilities.entitypatch.player.ServerPlayerPatch;

public class CPAnimationVariablePacket<T>
extends AnimationVariablePacket<T> {
    public CPAnimationVariablePacket(SynchedAnimationVariableKey<T> animationVariableKey, @Nullable AssetAccessor<? extends StaticAnimation> animation, T value, AnimationVariablePacket.Action action) {
        super(animationVariableKey, animation, value, action);
    }

    public static <T> CPAnimationVariablePacket<T> fromBytes(FriendlyByteBuf buf) {
        SynchedAnimationVariableKey variableKey = SynchedAnimationVariableKey.byId(buf.readInt());
        AnimationManager.AnimationAccessor animation = AnimationManager.byId(buf.readInt());
        AnimationVariablePacket.Action action = AnimationVariablePacket.Action.values()[buf.readInt()];
        return new CPAnimationVariablePacket<Object>(variableKey, animation, (action == AnimationVariablePacket.Action.PUT ? (T)variableKey.getPacketBufferCodec().decode(buf) : null), action);
    }

    public static <T> void toBytes(CPAnimationVariablePacket<T> msg, FriendlyByteBuf buf) {
        buf.writeInt(msg.animationVariableKey.getId());
        buf.writeInt(((StaticAnimation)msg.animation.get()).getId());
        buf.writeInt(msg.action.ordinal());
        if (msg.action == AnimationVariablePacket.Action.PUT) {
            msg.animationVariableKey.getPacketBufferCodec().encode(msg.value, buf);
        }
    }

    public static <T> void handle(CPAnimationVariablePacket<T> msg, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> EpicFightCapabilities.getUnparameterizedEntityPatch((Entity)((NetworkEvent.Context)ctx.get()).getSender(), ServerPlayerPatch.class).ifPresent(playerpatch -> {
            msg.process((LivingEntityPatch<?>)playerpatch);
            EpicFightNetworkManager.sendToAllPlayerTrackingThisEntity(new SPAnimationVariablePacket<Object>((LivingEntityPatch<?>)playerpatch, (SynchedAnimationVariableKey<Object>)msg.animationVariableKey, (AssetAccessor<StaticAnimation>)((AssetAccessor<? extends StaticAnimation>)msg.animation), msg.value, msg.action), playerpatch.getOriginal(), new Object[0]);
        }));
        ctx.get().setPacketHandled(true);
    }
}

